@php $tot = 0; foreach (DB::table('money_accounts')->get() as $a) $tot += $a->opening + DB::table('account_entries')->where('account_id',$a->id)->where('direction','income')->sum('amount') - DB::table('account_entries')->where('account_id',$a->id)->where('direction','expense')->sum('amount');
$inc = DB::table('account_entries as e')->leftJoin('money_accounts as a','a.id','=','e.account_id')->leftJoin('expense_purposes as p','p.id','=','e.purpose_id')->where('e.direction','income')->select('e.*','a.name as acc','p.name as pur')->orderByDesc('e.id')->limit(6)->get();
$wd = DB::table('withdraw_requests as w')->leftJoin('customers as c','c.id','=','w.customer_id')->select('w.*','c.name as cname')->orderByDesc('w.id')->limit(5)->get(); @endphp
<div class="card"><b>Total across all accounts: ৳{{ number_format($tot) }}</b> <span style="font-size:12px;color:#6B7280">Every order payment, advance, expense, transfer and supplier payment moves one of these accounts.</span> · <a href="/admin/m/entries/new" style="color:#FF5A00;font-weight:600">Add income or expense</a></div>
